function bindAnalyticsFilters(){const from=$('#analytics-from'),to=$('#analytics-to'),airport=$('#analytics-airport'),period=$('#analytics-period');if(!from)return;const now=new Date(),ymd=d=>d.toISOString().slice(0,10);function dates(){const year=now.getUTCFullYear(),month=now.getUTCMonth();if(period.value==='TODAY'){from.value=ymd(now);to.value=from.value}else if(period.value==='MONTH'){from.value=ymd(new Date(Date.UTC(year,month,1)));to.value=ymd(new Date(Date.UTC(year,month+1,0)))}else if(period.value==='LAST'){from.value=ymd(new Date(Date.UTC(year,month-1,1)));to.value=ymd(new Date(Date.UTC(year,month,0)))}}const result=()=>analyticsResult(from.value,to.value,airport.value);const apply=()=>{const data=result(),{rows,stations}=data;$('#analytics-trips').textContent=data.ids;$('#analytics-legs').textContent=rows.length;$('#analytics-tasks').textContent=data.tasks;$('#analytics-reports').textContent=data.reports;$('#analytics-requests').textContent=data.requests;$('#analytics-chart').innerHTML=Object.entries(stations).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([station,count])=>'<div class="analytics-bar"><span>'+esc(station)+'</span><i style="width:'+Math.max(4,Math.round(75*count/Math.max(1,...Object.values(stations))))+'%"></i><b>'+count+'</b></div>').join('');$('#analytics-stations').innerHTML=Object.entries(stations).sort((a,b)=>b[1]-a[1]).map(([station,count])=>'<div class="panel flight-card"><b>'+esc(station)+'</b><p>'+count+' STATION MOVEMENT(S)</p></div>').join('')||'<div class="panel empty">NO OPERATIONS IN THIS PERIOD.</div>';$('#analytics-flights').innerHTML=rows.map(({flight,l,j,day,i})=>'<div class="panel flight-card"><b>'+esc(day)+' · '+esc(l.handlingStation)+' · '+esc(flight.tripNumber||flight.flightNumber)+'</b><p>LEG '+(j+1)+' · '+esc(l.arrivingFrom)+' → '+esc(l.departingTo)+' · '+esc(flight.purpose||'')+' · '+esc(l.paymentMethod||'')+' · REPORT '+esc(l.reportStatus||'PENDING')+'</p><button type="button" class="btn outline" data-analytics-open="'+esc(flight.id||'ROW-'+i)+'">OPEN FLIGHT</button></div>').join('');$('#analytics-report-preview').replaceChildren()};period.onchange=()=>{dates();apply()};from.onchange=to.onchange=()=>{period.value='CUSTOM';apply()};airport.onchange=apply;$('#analytics-flights').onclick=e=>{const button=e.target.closest('[data-analytics-open]');if(!button)return;const f=[...state.transactions.activeFlights,...state.transactions.closedFlights].find((x,i)=>(x.id||'ROW-'+i)===button.dataset.analyticsOpen);if(f){draft=clone(f);route='create';render()}};const preview=()=>{const pages=analyticsReportCanvases(result());$('#analytics-report-preview').replaceChildren(...pages.map(c=>{const img=new Image();img.src=c.toDataURL('image/png');img.alt='Filtered analytics report preview';return img}));return pages};$('#analytics-preview').onclick=()=>preview();$('#analytics-share-png').onclick=()=>{const data=result();if(data.rows.length>8)return toast('MORE THAN 8 ROWS · USE PDF FOR ALL RESULTS');const pages=preview();actionQueue.push({type:'SAVE_PNG',name:'ANALYTICS-'+(airport.value||'ALL')+'.png',dataUrl:pages[0].toDataURL('image/png')});toast('PNG READY · CLOSE FLYPAD TO SHARE')};$('#analytics-share-pdf').onclick=()=>{const pages=preview();actionQueue.push({type:'RENDERED_DOCUMENTS',pages:pages.map((c,i)=>({name:'ANALYTICS-REPORT-'+(i+1),jpeg:c.toDataURL('image/jpeg',0.85)}))});toast('PDF READY · CLOSE FLYPAD TO SHARE')};dates();apply()}
