function personLine(record){const p=state.master.people.find(x=>x.id===record.personId)||record,passport=arr(p.passports)[0]||{};return upper(p.name||"PERSON")+' | '+upper(record.role||p.role||p.category||"")+' | '+upper(p.nationalityCode||"")+' | '+upper(passport.number||"")+' | '+String(passport.expiry||"")}
