function dispatchNative(payload){
  if(payload.type==='SAVE_STATE'){
    try{localStorage.setItem('FLYPAD_AZURE_SAMPLE_STATE',JSON.stringify(payload.state));return Promise.resolve('SAVED IN THIS BROWSER ONLY')}
    catch(error){return Promise.reject(Error('BROWSER TEST STORAGE FAILED: '+error.message))}
  }
  if(payload.type==='SAVE_DRAFTS'){
    try{localStorage.setItem('FLYPAD_DRAFTS_PENDING',JSON.stringify(payload.drafts));return Promise.resolve('DRAFT SAVED IN THIS BROWSER ONLY')}
    catch(error){return Promise.reject(Error('BROWSER TEST STORAGE FAILED: '+error.message))}
  }
  return Promise.reject(Error('THIS EXPORT NEEDS THE SCRIPTABLE APP. AZURE TEST HAS NO CLOUD STORAGE OR PDF SERVICE YET.'));
}
