function fitCanvasText(ctx,text,x,y,width,fontSize=18){ctx.font=fontSize+'px monospace';const words=String(text||'').split(/\s+/);let line='',lines=[];words.forEach(word=>{if(ctx.measureText(line+' '+word).width>width&&line){lines.push(line);line=word}else line+=(line?' ':'')+word});lines.push(line);lines.forEach((s,i)=>ctx.fillText(s,x,y+i*(fontSize+7)));return lines.length*(fontSize+7)}
