  const dof=p.dof||String(leg.departureDate||'').slice(2).replace(/-/g,'');let other=upper(p.item18||'');if(dof&&!/\bDOF\//.test(other))other+=(other?' ':'')+'DOF/'+dof;lines(other,88,820,1000,30,4);
  put(p.endurance,145,1020,110);put(p.pob||Number(leg.crewOut||0)+Number(leg.paxOut||0),416,1020,88);
  [['U',844],['V',936],['E',1028]].forEach(([code,x])=>mark(p.radioCodes,code,x,1018));
  [['P',243],['D',328],['M',420],['J',510]].forEach(([code,x])=>mark(p.survivalCodes,code,x,1110));
  [['L',750],['F',841],['U',931],['V',1023]].forEach(([code,x])=>mark(p.jacketsCodes,code,x,1110));
  put(p.dinghiesNumber,152,1199,52);put(p.dinghiesCapacity,235,1199,75);if(p.dinghiesCovered==='YES')mark(['C'],'C',355,1197);put(p.dinghiesColor,421,1199,245);
