      for(const type of request.docs){
        if(type==='COMBINED FLIGHT REPORT'||type==='TRIP ITINERARY'){
          const canvases=FLYPADDocuments.render(type,request.flight,null,0,state.master.people,logo,state.master.companyName,state.master.companyContacts,state.master.documentDesign,window.__gdStampImage,window.__gdSignatureImage,window.__footerLogoImage);
          canvases.forEach((c,i)=>pages.push({name:request.flight.tripNumber+(type==='TRIP ITINERARY'?'-ALL-ITINERARY-':'-ALL-REPORT-')+(i+1),jpeg:c.toDataURL('image/jpeg',0.82)}));
        }else for(const index of request.legIndexes){
          const canvases=await renderOne(type,request,index,logo);
          canvases.forEach((c,i)=>pages.push({name:request.flight.tripNumber+'-L'+(index+1)+'-'+type+'-'+(i+1),jpeg:c.toDataURL('image/jpeg',0.82)}));
        }
      }
      if(finalDocs){request.flight.invoiceIssues=arr(request.flight.invoiceIssues);request.flight.invoiceIssues.push({issuedAt:new Date().toISOString(),legIndexes:request.legIndexes,types:request.docs.filter(x=>x==='CASH INVOICE'||x==='CREDIT HANDLING SHEET'),profitCurrency:request.flight.profitCurrency||'AED',services:request.legIndexes.flatMap(i=>arr(request.flight.legs[i].services).filter(s=>upper(s.status)==='USED').map(s=>({legIndex:i,description:s.description,quantity:s.quantity,rate:s.chargeAmount,currency:s.sellingCurrency,taxPercentage:s.taxPercentage,rateSnapshot:s.rateSnapshot}))) });await queueSave()}const action={type:'RENDERED_DOCUMENTS',pages};actionQueue.push(action);
