function staffReportOptions(){const form=$('#staff-entry-form'),r=$('[name="reportStaff"]');return{staff:upper(r?.value||form?.elements.staff?.value),currency:upper($('[name="reportCurrency"]')?.value||'AED'),from:$('[name="reportFrom"]')?.value,to:$('[name="reportTo"]')?.value,status:$('#report-receipt-status')?.checked,images:$('#report-receipt-images')?.checked}}
function staffReportData(o){const all=staffAccountEntries(o.staff,o.currency),entries=all.filter(x=>x.date>=o.from&&x.date<=o.to),opening=staffBalance(o.staff,o.currency,o.from),received=entries.filter(x=>x.kind!=='DEBIT').reduce((s,x)=>s+Number(x.amount),0),spent=entries.filter(x=>x.kind==='DEBIT').reduce((s,x)=>s+Number(x.amount),0),categories={},flights=staffFlightOptions(),groups=new Map();entries.filter(x=>x.kind==='DEBIT').forEach(x=>{const p=upper(x.purpose||'OTHER');categories[p]=(categories[p]||0)+Number(x.amount);const f=flights.find(y=>y.id===x.flightId),l=f&&arr(f.legs).find(y=>y.id===x.legId),key=(x.flightId||'OFFICE')+'|'+(x.legId||'');let g=groups.get(key);if(!g){g={date:x.date,flight:f?.flightNumber||f?.tripNumber||'OFFICE',registration:f?.aircraftRegistration||'',station:l?.handlingStation||'—',purposes:new Set(),amount:0,entries:0,receiptsMissing:0};groups.set(key,g)}g.purposes.add(p);g.amount+=Number(x.amount);g.entries++;if(!x.receiptData)g.receiptsMissing++});return{...o,entries,opening,received,spent,closing:opening+received-spent,categories,flightCount:new Set(entries.filter(x=>x.kind==='DEBIT'&&x.flightId).map(x=>x.flightId)).size,rows:[...groups.values()].map(x=>({...x,purpose:[...x.purposes].join(', ')})),missing:entries.filter(x=>x.kind==='DEBIT'&&!x.receiptData).length}}
